/**
 * Rebuilds/updates the local SQLite DB from every dated JSON snapshot in
 * data/seeds/. Those files are committed to git, so they are the durable
 * source of truth for accumulated recall data — the SQLite file itself is
 * gitignored and treated as a disposable local cache that can always be
 * regenerated by replaying the seed files (upserts are idempotent).
 *
 * Filename convention: {domestic|overseas}-YYYY-MM-DD[-suffix].json
 * Each file is either { source_type, raw: [...] } or a bare array (in
 * which case the source_type is inferred from the filename prefix).
 *
 * Usage: npm run seed
 */
import fs from "node:fs";
import path from "node:path";
import { upsertRecalls } from "../src/db";
import { normalize } from "../src/normalize";
import { SourceType } from "../src/types";

const SEEDS_DIR = path.resolve(__dirname, "..", "data", "seeds");

function inferSourceType(fileName: string): SourceType | null {
  if (fileName.startsWith("domestic")) return "domestic";
  if (fileName.startsWith("overseas")) return "overseas";
  return null;
}

function main() {
  if (!fs.existsSync(SEEDS_DIR)) {
    console.error(`No seeds directory at ${SEEDS_DIR}`);
    process.exit(1);
  }

  const files = fs
    .readdirSync(SEEDS_DIR)
    .filter((f) => f.endsWith(".json"))
    .sort();

  if (files.length === 0) {
    console.error("No seed files found.");
    process.exit(1);
  }

  let totalIngested = 0;
  for (const file of files) {
    const fullPath = path.join(SEEDS_DIR, file);
    const parsed = JSON.parse(fs.readFileSync(fullPath, "utf-8"));
    const rawItems: unknown[] = Array.isArray(parsed) ? parsed : parsed.raw ?? parsed.data ?? [];
    const sourceType: SourceType | null = Array.isArray(parsed)
      ? inferSourceType(file)
      : parsed.source_type ?? inferSourceType(file);

    if (!sourceType) {
      console.warn(`Skipping ${file}: cannot determine source_type (filename should start with 'domestic' or 'overseas')`);
      continue;
    }
    if (rawItems.length === 0) {
      console.warn(`Skipping ${file}: no records`);
      continue;
    }

    const normalized = rawItems.map((item) => normalize(sourceType, item));
    const result = upsertRecalls(normalized);
    totalIngested += result.inserted;
    console.log(`${file}: ${result.inserted} ${sourceType} records upserted`);
  }

  console.log(`Done. ${totalIngested} records processed from ${files.length} seed file(s).`);
}

main();
